package plates.ui

import kotlinx.browser.window
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.MainScope
import kotlinx.coroutines.launch
import org.w3c.dom.HTMLElement

/** The page clock for [PlateCanvas]'s `now`, so animations run in real time. */
fun pageNow(): Double = window.performance.now()

/**
 * [D2][D7] Mounts [canvas] in [host]: its retained [PlateSurface], and one native `<input>` per
 * [PlateCanvas.slotInputs] box over it. The plate repaints on [PlateCanvas.wakes] and once per animation frame while
 * it moves [H11]; the inputs are synced only when the values change, so focus and caret stay.
 */
fun mountPlate(host: HTMLElement, canvas: PlateCanvas, scope: CoroutineScope = MainScope()): Job {
    host.style.position = "relative"
    val surface = PlateSurface(canvas.id)
    host.appendChild(surface.element)
    val inputs = canvas.slotInputs().associate { s ->
        s.index to slotInputElement(s, "", canvas.spec.canvasWidth, canvas.spec.canvasHeight).also { input ->
            input.oninput = { canvas.controller.setAt(s.index, input.value.ifEmpty { null }) }
            host.appendChild(input)
        }
    }
    fun sync() = inputs.forEach { (i, input) ->
        val v = canvas.values.getOrNull(i) ?: ""
        if (input.value != v) input.value = v
    }
    val loop = FrameLoop(canvas) { surface.paint(it) }
    loop.frame()
    sync()
    return scope.launch {
        launch { canvas.controller.changes.collect { sync() } }
        canvas.wakes.collect { loop.request() }
    }.also { job -> job.invokeOnCompletion { loop.stop() } }
}

